def _rand_utf8(r: random.Random, length: int) -> bytes:
    # Generate mostly-valid UTF-8 with occasional control bytes
    out = bytearray()
    while len(out) < length:
        t = r.random()
        if t < 0.6:
            # ASCII printable
            out.append(r.randint(0x20, 0x7E))
        elif t < 0.7:
            # Controls (including NUL)
            out.append(r.choice([0x00, 0x09, 0x0A, 0x0D, 0x1B]))
        elif t < 0.85:
            # 2-byte sequence
            c1 = r.randint(0xC2, 0xDF)
            c2 = r.randint(0x80, 0xBF)
            out.extend([c1, c2])
        elif t < 0.95:
            # 3-byte sequence
            c1 = r.randint(0xE0, 0xEF)
            c2 = r.randint(0x80, 0xBF)
            c3 = r.randint(0x80, 0xBF)
