def _rand_printable_with_escapes(r: random.Random, length: int) -> bytes:
    tokens = [
        b"IN_ACCESS", b"IN_ATTRIB", b"IN_CLOSE_WRITE", b"IN_CLOSE_NOWRITE",
        b"IN_CREATE", b"IN_DELETE", b"IN_DELETE_SELF", b"IN_MODIFY",
        b"IN_MOVE_SELF", b"IN_MOVED_FROM", b"IN_MOVED_TO", b"IN_OPEN",
        b"IN_IGNORED", b"IN_Q_OVERFLOW", b"IN_UNMOUNT",
    ]
    seps = [b"|", b",", b" ", b"\t", b"/", b"::", b";", b"+"]
    parts: List[bytes] = []
    printable_bytes = [ord(ch) for ch in string.printable[:-6]]  # exclude non-printable whitespace
    while sum(len(p) for p in parts) < length:
        choice = r.random()
        if choice < 0.6:
            parts.append(r.choice(tokens))
        elif choice < 0.8:
            parts.append(r.choice(seps))
        else:
            # random printable chunk
            L = r.randint(1, max(1, min(32, length)))
            chunk = bytes(r.choice(printable_bytes) for _ in range(L))
            parts.append(chunk)
    data = b"".join(parts)[:length]
    return data

def _rand_high_entropy(r: random.Random, length: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(length))

def _rand_repeated_runs(r: random.Random, length: int) -> bytes:
    out = bytearray()
    while len(out) < length:
        run_len = r.randint(1, min(256, length - len(out)))
        bval = r.getrandbits(8)
        out.extend([bval] * run_len)
    return bytes(out[:length])

def _rand_paths_and_names(r: random.Random, length: int) -> bytes:
    # Mix of paths, filenames, and separators, with occasional NULs
    path_seps = [b"/", b"//", b"/./", b"/../"]
    names = [
        b"home", b"user", b"tmp", b"var", b"log", b"dev", b"proc", b"sys",
        b"very_long_directory_name", b"file.txt", b"a.out", b"data.bin",
        b"sp ace", b"comma,here", b"semi;colon", b"pipe|name", b"quote\"d",
    ]
    out = bytearray()
    while len(out) < length:
        choice = r.random()
        if choice < 0.1:
            out.append(0)  # embedded NUL
        elif choice < 0.2:
            # add wildcard or regex-like bits
            out.extend(r.choice([b".*", b"^", b"$", b"[A-Za-z0-9_]+", b"(foo|bar)"]))
        elif choice < 0.6:
            out.extend(r.choice(path_seps))
            out.extend(r.choice(names))
        else:
            # random chunk
            L = r.randint(1, 16)
            out.extend(_rand_high_entropy(r, L))
    return bytes(out[:length])

def _compose_chunks(r: random.Random, target_len: int) -> bytes:
    builders = [_rand_utf8, _rand_printable_with_escapes, _rand_high_entropy, _rand_repeated_runs, _rand_paths_and_names]
    out = bytearray()
    # Optional small header-like variability
    if r.random() < 0.4 and target_len >= 8:
        mode = r.randint(0, 4)
        out.extend(struct.pack('<I', target_len))
        out.append(mode)
        out.append(0)  # reserved
        out.extend(b"\x00\x00")
    while len(out) < target_len:
        remaining = target_len - len(out)
        builder = r.choice(builders)
        if remaining <= 0:
            break
        if r.random() < 0.75:
            clen = r.randint(1, min(64, remaining))
        else:
            # pick a larger chunk only if remaining allows, otherwise fall back to remaining
            low = 65
            if remaining < low:
                clen = remaining
            else:
                clen = r.randint(low, remaining)
        out.extend(builder(r, clen))
    return bytes(out[:target_len])

def _choose_length(r: random.Random) -> int:
    # Favor edge lengths around 0, small, typical, and near MAX_STRLEN
    choices = [
        0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 512, 1023, 1024,
        MAX_STRLEN - 3, MAX_STRLEN - 2, MAX_STRLEN - 1, MAX_STRLEN,
    ]
    if r.random() < 0.5:
        return r.choice(choices)
    return r.randint(0, MAX_STRLEN)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    length = _choose_length(r)

    # Weighted strategy selection
    strategy = r.choices(
        population=["utf8", "printable", "entropy", "runs", "paths", "compose"],
        weights=[20, 15, 20, 15, 10, 20],
        k=1,
    )[0]

    if strategy == "utf8":
        data = _rand_utf8(r, length)
    elif strategy == "printable":
        data = _rand_printable_with_escapes(r, length)
    elif strategy == "entropy":
        data = _rand_high_entropy(r, length)
    elif strategy == "runs":
        data = _rand_repeated_runs(r, length)
    elif strategy == "paths":
        data = _rand_paths_and_names(r, length)
    else:
        data = _compose_chunks(r, length)

    if len(data) > MAX_STRLEN:
        data = data[:MAX_STRLEN]
    return data
